function HasCloseElements(numbers: array of real; threshold: real): boolean;
begin
  var sorted := numbers.ToArray;
  sorted.Sort;
  for var i := 0 to sorted.Length - 1 do
    for var j := i + 1 to sorted.Length - 1 do
      if Abs(sorted[i] - sorted[j]) < threshold then
      begin
        Result := True;
        exit;
      end;
  Result := False;
end;


function SeparateParenGroups(parenString: string): array of string;
begin
  var stack := new Stack<char>;
  var groups := new List<string>;
  var currentGroup := new StringBuilder;

  for var i := 1 to parenString.Length do
  begin
    var ch := parenString[i];
    if ch = ' ' then
      continue;

    if ch = '(' then
      stack.Push(ch)
    else
    begin
      if stack.Count = 0 then
        currentGroup.Append(ch)
      else
      begin
        var top := stack.Peek;
        if top = '(' then
        begin
          if currentGroup.Length > 0 then
          begin
            groups.Add(currentGroup.ToString);
            currentGroup.Clear;
          end;
          stack.Pop;
        end
        else
          currentGroup.Append(ch);
      end;
    end;
  end;

  if currentGroup.Length > 0 then
    groups.Add(currentGroup.ToString);

  Result := groups.ToArray;
end;


