function ParseNestedParens(parenString: string): array of integer;
begin
  var groups := parenString.Split(' ');
  var levels := new List<integer>;
  var maxLevel := 0;
  var currentLevel := 0;

  foreach var group in groups do
  begin
    for var i := 1 to group.Length do
    begin
      if group[i] = '(' then
        currentLevel += 1
      else
        currentLevel -= 1;

      if currentLevel > maxLevel then
        maxLevel := currentLevel;
    end;
    levels.Add(maxLevel);
  end;

  Result := levels.ToArray;
end;


