function MakePalindrome(str: string): string;
begin
  var postfix := '';
  for var i := 1 to str.Length div 2 do
    if str[i] <> str[str.Length - i + 1] then
      break;
    else
      postfix := str[i] + postfix + str[i];
  Result := str + ReverseString(postfix);
end;


