function Factorize(n: integer): array of integer;
begin
  var i := 2;
  var n1 := n;
  var factors := new List<integer>;
  while i * i <= n1 do
  begin
    if n1 mod i = 0 then
    begin
      n1 := n1 div i;
      factors.Add(i);
    end
    else
      i += 1;
  end;
  if n1 > 1 then
    factors.Add(n1);
  Result := factors.ToArray;
end;


