function Poly(xs : array of real; x : real): real;
{ Evaluates polynomial with coefficients xs at point x.
    return xs[0] + xs[1] * x + xs[1] * x^2 + .... xs[n] * x^n }
begin
  var _result := 0.0;
  for var i := 0 to xs.Length - 1 do
    _result := _result + xs[i] * Power(x, i);
  Result := _result;
end;
function FindZero(xs: array of real): real;
begin
  var a := xs[0];
  var b := xs[xs.Length - 1];
  var eps := 1e-10;
  var left := Min(a, b);
  var right := Max(a, b);
  while Abs(right - left) > eps do
  begin
    var mid := (left + right) / 2;
    if Poly(xs, mid) * Poly(xs, left) < 0 then
      right := mid
    else
      left := mid;
  end;
  Result := (left + right) / 2;
end;


