function ChangeBase(x: integer; base: integer): string;
begin
  if not (base in 2..10) then
    raise new System.ArgumentException('Base must be in [2..10]');
  if x < 0 then
    raise new System.ArgumentException('Input number must be non-negative');
  var sb := new System.Text.StringBuilder;
  while x > 0 do
  begin
    sb.Insert(0, char(x mod base + ord('0')));
    x := x div base;
  end;
  Result := sb.ToString;
end;


