  &Array.Sort(temp);

  var res := new integer[lst.Length];
  var left := 0;
  var right := lst.Length - 1;
  var index := 0;

  while left <= right do
  begin
    if left = right then
    begin
      res[index] := temp[left];
      break;
    end;

    res[index] := temp[right];
    res[index + 1] := temp[left];
