function SmallestChange(arr: array of integer): integer;
begin
  var n := arr.Length;
  var dp := new integer[n + 1, n + 1];

  for var i := 0 to n do
    dp[i, i] := 0;

  for var len := 2 to n do
  begin
    for var i := 0 to n - len do
    begin
      var j := i + len;
      dp[i, j] := dp[i + 1, j - 1] + 
        (if arr[i] = arr[j] then 0 else 1) + dp[i, j - 1];

      for var k := i to j - 1 do
        if arr[i] = arr[k] then
        begin
          var temp := dp[i, k] + dp[k + 1, j];
          if temp < dp[i, j] then
            dp[i, j] := temp;
        end;
    end;
  end;

  Result := dp[0, n - 1];
end;


