function AntiShuffle(s: string): string;
begin
  var words := s.Split(' ');
  var sorted := new List<string>;
  var current := new List<char>;
  var currentChar := 0;
  var currentWord := '';

  foreach var word in words do
  begin
    if word = '' then
    begin
      sorted.Add(string.Join('', current));
      current.Clear;
      continue;
    end;

    for var i := 1 to word.Length do
    begin
      if word[i] = ' ' then
      begin
        sorted.Add(string.Join('', current));
        current.Clear;
        currentWord := '';
        continue;
      end;

      if word[i] < currentChar then
        current.Add(word[i])
      else
      begin
        current.Add(currentChar);
        currentChar := word[i] + 1;
        currentWord += word[i];
      end;
    end;

    if currentWord.Length > 0 then
    begin
      sorted.Add(currentWord);
      current.Clear;
    end;
  end;

  Result := string.Join('', sorted);
end;


