function MaxFill(grid: array of array of integer; capacity: integer): integer;
begin
  var m := grid.Length;
  var n := grid[0].Length;
  var res := 0;
  var buckets := new integer[m, n];

  for var i := 0 to m - 1 do
    for var j := 0 to n - 1 do
      if grid[i][j] = 1 then
        buckets[i, j] := capacity;

  for var i := 0 to m - 1 do
  begin
    for var j := 0 to n - 1 do
    begin
      if buckets[i, j] > 0 then
      begin
        var down := 0;
        var right := 0;

        if (i + 1 < m) and (grid[i + 1][j] = 1) then
          down := 1;

        if (j + 1 < n) and (grid[i][j + 1] = 1) then
          right := 1;

        if (down = 1) and (right = 1) then
        begin
          buckets[i, j] -= 1;
          buckets[i + 1, j] -= 1;
          buckets[i, j + 1] -= 1;
        end
        else if down = 1 then
          buckets[i, j] -= 1;
        else if right = 1 then
          buckets[i, j] -= 1;
      end;
    end;
  end;

  for var i := 0 to m - 1 do
    for var j := 0 to n - 1 do
      if buckets[i, j] > 0 then
        res += 1;

  Result := res;
end;


