function GetClosestVowel(word: string): string;
begin
  var vowels := HSet('a', 'e', 'i', 'o', 'u', 'A', 'E', 'I', 'O', 'U');
  var maxLen := 0;
  var maxVowel := '';
  var consonants := HSet('b', 'c', 'd', 'f', 'g', 'h', 'j', 'k', 'l', 'm', 'n', 'p', 'q', 'r', 's', 't', 'v', 'w', 'x', 'y', 'z', 'B', 'C', 'D', 'F', 'G', 'H', 'J', 'K', 'L', 'M', 'N', 'P', 'Q', 'R', 'S', 'T', 'V', 'W', 'X', 'Y', 'Z');
  var right := word.Reverse.ToArray;

  for var i := right.Length - 1 downto 0 do
  begin
    if consonants.Contains(right[i]) then
    begin
      var left := i - 1;
      while (left >= 0) and consonants.Contains(right[left]) do
        left -= 1;

      var len := i - left;
      if len > maxLen then
      begin
        maxLen := len;
        maxVowel := if vowels.Contains(right[left]) then right[left] else right[i];
      end;
    end;
  end;

  Result := maxVowel;
end;


