  var sum := 0;

  foreach var num in arr do
  begin
    if num < 0 then
      sign := -1
    else if num > 0 then
      sign := 1;

    sum += Abs(num);
    prod *= sign;
  end;

  Result := prod * sum;
end;


function Minpath(grid: array of array of integer; k: integer): array of integer;
begin
  var n := grid.Length;
  var directions := new integer[4]((-1, 0), (0, 1), (1, 0), (0, -1));
  var visited := new boolean[n, n];
  var queue := new Queue<(integer, integer, integer)>;
  var ans := new List<integer>;

  for var i := 0 to n - 1 do
    for var j := 0 to n - 1 do
    begin
      if (i = 0) and (j = n - 1) then
      begin
        visited[i, j] := True;
        queue.Enqueue((i, j, 0));
        ans.Add(grid[i][j]);
      end;
    end;

  while queue.Count > 0 do
  begin
    var (i, j, steps) := queue.Dequeue;

    if steps = k then
    begin
      ans.Clear;
      ans.Add(grid[i][j]);
      break;
    end;

    for var d in directions do
    begin
      var (di, dj) := (d[0], d[1]);
      var ni := i + di;
      var nj := j + dj;

      if (ni >= 0) and (ni < n) and (nj >= 0) and (nj < n) and not visited[ni, nj] then
      begin
        visited[ni, nj] := True;
        queue.Enqueue((ni, nj, steps + 1));
        ans.Add(grid[ni][nj]);
      end;
    end;
  end;

  Result := ans.ToArray;
end;


function Tri(n: integer): array of real;
