  trib.Add(1);
  if n = 1 then
  begin
    Result := trib.ToArray;
    exit;
  end;
  trib.Add(2);
  for var i := 3 to n do
  begin
    if i mod 2 = 0 then
      trib.Add(1 + i div 2)
    else
      trib.Add(trib[i-1] + trib[i-2] + trib[i-3]);
  end;
  Result := trib.ToArray;
end;


