function IsNested(s: string): boolean;
begin
  var stack := new Stack<char>;
  foreach var ch in s do
  begin
    if (ch = '[') or (ch = '{') or (ch = '(') then
      stack.Push(ch)
    else if (ch = ']') or (ch = '}') or (ch = ')') then
    begin
      if stack.Count = 0 then
      begin
        Result := False;
        exit;
      end;
      var top := stack.Pop;
      if (ch = ']') and (top <> '[') then
      begin
        Result := False;
        exit;
      end;
      if (ch = '}') and (top <> '{') then
      begin
        Result := False;
        exit;
      end;
      if (ch = ')') and (top <> '(') then
      begin
        Result := False;
        exit;
      end;
    end;
  end;
  Result := stack.Count = 0;
end;


